    // forbidden writing for a while
    std::lock_guard write_lock(write_mtx_);

    if (writing_segment_->doc_count() != 0) {
      // flush and create new segment
      auto s = switch_to_new_segment_for_writing();
      if (!s.ok()) {
        return s;
      }
    }

